   for(let i=defenses.length-1;i>=0;i--){const d=defenses[i];d.age+=delta;const p=Math.min(1,d.age/d.duration);if(d.kind==='shield'){d.mesh.scale.setScalar(1+p*2);d.mesh.material.opacity=(1-p)*.6;d.wave.scale.setScalar(.3+p*2.5);d.wave.material.opacity=(1-p)*.9;}else{const point=d.start.clone().lerp(d.end,p);d.ball.position.copy(point);const attr=d.line.geometry.attributes.position;attr.setXYZ(0,...d.start.clone().lerp(d.end,Math.max(0,p-.2)).toArray());attr.setXYZ(1,...point.toArray());attr.needsUpdate=true;d.line.geometry.computeBoundingSphere();}if(p>=1){if(d.kind==='interceptor'&&!d.success)burst(d.end,0x8cb8d8,.22);dispose(d.group);defenses.splice(i,1);}}
   for(const s of scars){s.age+=delta;s.smoke.material.opacity=.12+.08*(.5+.5*Math.sin(s.age*1.8));s.smoke.scale.setScalar(.16*(1+.08*Math.sin(s.age*1.3)));}
   if(cinematic){const v=visuals.get(cinematic.id);if(v){const p=v.body.position,desired=p.clone().normalize().multiplyScalar(6.2);camera.position.lerp(desired,1-Math.exp(-dt*3));controls.target.lerp(p.clone().multiplyScalar(.65),1-Math.exp(-dt*3));}else{cinematic.linger-=dt;if(cinematic.linger<=0)stopCinema();}}
